insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (2, 16, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1021) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "حُبِّبَ إِلَيَّ مِنَ الدُّنْيَا النِّسَاءُ وَالطِّيبُ، وَجُعِلَتْ -وجعلت- قُرَّةَ عَيْنِي فِي الصَّلَاةِ". (ن)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ദുനിയാവിലെ വസ്തുക്കളിൽ ഭാര്യയും സുഗന്ധവുമാണ് എനിക്കിഷ്ടപ്പെട്ടത്. പക്ഷേ, എന്റെ കൺകുളിർമ നിസ്കാരത്തിലാണ്." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 831, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمْ يَكُنْ شَيْءٌ أَحَبَّ إِلَى رَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ بَعْدَ النِّسَاءِ مِنَ الْخَيْلِ. (ن)', 'അനസുബ്നു മാലിക്(റ): ഭാര്യമാർക്ക് ശേഷം കുതിരയേക്കാൾ നബി(സ)ക്ക് ഇഷ്ടമുള്ള ഒരു കാര്യവുമുണ്ടായിരുന്നില്ല. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 831, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ لَهُ امْرَأَتَانِ يَمِيلُ لِإِحْدَاهُمَا عَلَى الْأُخْرَى جَاءَ يَوْمَ الْقِيَامَةِ أَحَدُ شِقَّيْهِ مَائِلٌ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "രണ്ട് ഭാര്യമാരുള്ളവൻ ഒരു ഭാര്യയോട് കൂടുതൽ അടുപ്പം കാണിച്ചാൽ ഒരു ഭാഗം കുഴഞ്ഞവനായിട്ടായിരിക്കും അന്ത്യനാളിൽ അവൻ വരിക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 831, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَائِشَةَ رَضِيَ الله عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ يَقْسِمُ بَيْنَ نِسَائِهِ ثُمَّ يَعْدِلُ، ثُمَّ يَقُولُ: "اللَّهُمَّ هَذَا فِعْلِي فِيمَا أَمْلِكُ، فَلَا تَلُمْنِي فِيمَا تَمْلِكُ وَلَا أَمْلِكُ". (ن)', 'ആഇശ(റ): തിരുദൂതർ(സ) ഭാര്യമാർക്കിടയിൽ ഭാഗിക്കുമ്പോൾ നീതി പുലർത്തുകയും ഇപ്രകാരം പറയുകയും ചെയ്യുമായിരുന്നു. "അല്ലാഹുവേ, ഇതെന്റെ കഴിവനുസരിച്ചുള്ള പ്രവർത്തനമാണ്. നിനക്ക് കഴിയുന്നതും എനിക്ക് കഴിയാത്തതുമായ കാര്യത്തിൽ നീ എന്നെ ആക്ഷേപിക്കരുത്." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 831, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَائِشَةَ رَضِيَ الله عَنْهَا قَالَتْ: أَرْسَلَ أَزْوَاجُ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ فَاطِمَةَ بِنْتَ رَسُولِ اللهِ صَلَّى اللهِ عَلَيْهِ وَسَلَّمَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَأْذَنَتْ عَلَيْهِ وَهُوَ مُضْطَجِعٌ مَعِي فِي مِرْطِي، فَأَذِنَ لَهَا، فَقَالَتْ: يَا رَسُولَ اللهِ، إِنَّ أَزْوَاجَكَ أَرْسَلْنَنِي إِلَيْكَ يَسْأَلْنَكَ الْعَدْلَ فِي ابْنَةِ أَبِي قُحَافَةَ. وَأَنَا سَاكِتَةٌ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيْ بُنَيَّةُ، أَلَسْتِ تُحِبِّينَ مَنْ أُحِبُّ؟". قَالَتْ: بَلَى. قَالَ: "فَأَحِبِّي هَذِهِ". فَقَامَتْ فَاطِمَةُ حِينَ سَمِعَتْ ذَلِكَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَجَعَتْ إِلَى أَزْوَاجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرَتْهُنَّ بِالَّذِي قَالَتْ وَالَّذِي قَالَ لَهَا، فَقُلْنَ لَهَا: مَا نَرَاكِ أَغْنَيْتِ عَنَّا مِنْ شَيْءٍ، فَارْجِعِي إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُولِي لَهُ: إِنَّ أَزْوَاجَكَ يَنْشُدْنَكَ الْعَدْلَ فِي ابْنَةِ أَبِي قُحَافَةَ. قَالَتْ فَاطِمَةُ: لَا وَاللهِ لَا أُكَلِّمُهُ فِيهَا أَبَدًا. قَالَتْ عَائِشَةُ: فَأَرْسَلَ أَزْوَاجُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ زَيْنَبَ بِنْتَ جَحْشٍ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهِيَ الَّتِي كَانَتْ تُسَامِينِي مِنْ أَزْوَاجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَنْزِلَةِ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَمْ أَرَ امْرَأَةً قَطُّ خَيْرًا فِي الدِّينِ مِنْ زَيْنَبَ وَأَتْقَى لِلَّهِ عَزَّ وَجَلَّ، وَأَصْدَقَ حَدِيثًا وَأَوْصَلَ لِلرَّحِمِ، وَأَعْظَمَ صَدَقَةً وَأَشَدَّ ابْتِذَالًا لِنَفْسِهَا فِي الْعَمَلِ الَّذِي تَصَدَّقُ بِهِ، وَتَقَرَّبُ بِهِ مَا عَدَا سَوْرَةً مِنْ حِدَّةٍ كَانَتْ فِيهَا تُسْرِعُ مِنْهَا الْفَيْئَةَ، فَاسْتَأْذَنَتْ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَعَ عَائِشَةَ فِي مِرْطِهَا، عَلَى الْحَالِ الَّتِي كَانَتْ دَخَلَتْ فَاطِمَةُ عَلَيْهَا، فَأَذِنَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ، إِنَّ أَزْوَاجَكَ أَرْسَلْنَنِي يَسْأَلْنَكَ الْعَدْلَ فِي ابْنَةِ أَبِي قُحَافَةَ. وَوَقَعَتْ بِي فَاسْتَطَالَتْ، وَأَنَا أَرْقُبُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَرْقُبُ طَرْفَهُ: هَلْ أَذِنَ لِي فِيهَا؟ فَلَمْ تَبْرَحْ زَيْنَبُ حَتَّى عَرَفْتُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَكْرَهُ أَنْ أَنْتَصِرَ، فَلَمَّا وَقَعْتُ بِهَا لَمْ أُنْشِبْهَا بِشَيْءٍ حَتَّى أَنْحَيْتُ عَلَيْهَا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهَا ابْنَةُ أَبِي بَكْرٍ". (ن)', 'ആഇശ(റ): നബി(സ)യുടെ ഭാര്യമാർ ഫാതിമാബീവിയെ തിരുദൂതരുടെ അടുക്കലേക്ക് പറഞ്ഞയച്ചു. അവർ വന്ന് നബി(സ)യോട് വീട്ടിൽ പ്രവേശിക്കാൻ സമ്മതം ചോദിച്ചു. അപ്പോൾ നബി(സ) എന്റെ കൂടെ എന്റെ വിരിപ്പിൽ കിടക്കുകയായിരുന്നു. നബി(സ) അവർക്ക് സമ്മതം കൊടുത്തു. അവർ പറഞ്ഞു: തിരുദൂതരെ, ബിൻത് അബീകുഹാഫ (ആഇശ(റ)) യുടെ കാര്യത്തിൽ നീതി നടപ്പാക്കണമെന്നാവശ്യപ്പെട്ട് അങ്ങയുടെ ഭാര്യമാരാണ് എന്നെ (ഇങ്ങോട്ട്) അയച്ചിരിക്കുന്നത്. എനിക്കതിൽ ഒന്നും പറയാനില്ല. തിരുമേനി(സ) പറഞ്ഞു: "പൊന്നു മോളെ, ഞാൻ സ്നേഹിക്കുന്നവരെ നീ സ്നേഹിക്കുന്നില്ലേ." മഹതി പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "എങ്കിൽ ഇവളെ നീ സ്നേഹിക്കുക." ഇതു കേട്ടപ്പോൾ ഫാതിമബീവി(റ) എഴുന്നേറ്റ് നബി(സ)യുടെ ഭാര്യമാരുടെ അടുത്ത് ചെന്നു. അവർ നബി(സ)യോട് പറഞ്ഞതും നബി(സ) അവരോട് പറഞ്ഞതും വിവരിച്ചു കൊടുത്തു. അപ്പോഴവർ ഫാതിമബീവി(റ)യോട് പറഞ്ഞു: ഞങ്ങളുടെ ആവശ്യം നീ നിറവേറ്റിയില്ല. അതുകൊണ്ട് തിരുദൂതരു(സ)ടെ അടുത്തേക്ക് മടങ്ങുകയും ഇപ്രകാരം പറയുകയും ചെയ്യുക. അബുഖുഹാഫയുടെ മകളുടെ കാര്യത്തിൽ അങ്ങയുടെ ഭാര്യമാർ അങ്ങയോട് നീതി നടപ്പാക്കണമെന്നാവശ്യപ്പെടുന്നു. അപ്പോൾ ഫാതിമ(റ) പറഞ്ഞു: അല്ലാഹുവാണെ! ഇനി ഞാനീ വിഷയത്തിൽ തിരുമേനിയുമായി ഒരു വാക്കു പോലും സംസാരിക്കുകയില്ല. ആഇശ(റ) തുടരുന്നു: അതോടെ പ്രവാചക പത്നിമാർ സൈനബ(റ)യെ തിരുമേനി(സ)യുടെ അടുത്തേക്ക് പറഞ്ഞയച്ചു. തിരുമേനി(സ)യുടെ അടുക്കൽ സ്ഥാനംകൊണ്ട് അവിടുത്തെ പത്നിമാരിൽ ഞങ്ങൾ രണ്ടുപേരും ഒരു പോലെയാണ്. സൈനബ ബീവിയേക്കാൾ ദീനിന്റെ കാര്യത്തിൽ ഉത്തമയായ, അല്ലാഹുവിനെ ഏറ്റവും ഭയക്കുന്ന, സംസാരത്തിൽ സത്യം പറയുന്ന, കുടുംബ ബന്ധം ചേർക്കുന്ന, നല്ലവണ്ണം ദാനം ചെയ്യുന്ന സത്യവതിയാവാനും അല്ലാഹുവിലേക്കടുക്കുവാനും പരിശ്രമിക്കുന്ന ഒരു സ്ത്രീയെയും ഞാൻ കണ്ടിട്ടില്ല. പരുക്കൻ സ്വഭാവത്തിൽ നിന്നുണ്ടാകുന്ന ഒരു തരം ധൃതിയുണ്ട് എന്നതൊഴികെ, അവർ വന്ന് നബി(സ)യോട് സമ്മതം ചോദിച്ചു. നബി(സ) അപ്പോൾ ഫാതിമബീവി(റ) വന്നിരുന്ന സമയത്തെ അതേ അവസ്ഥയിൽ ആഇശ(റ)യുടെ വിരിപ്പിൽ മഹതിയോടൊപ്പം കിടക്കുകയായിരുന്നു. തിരുമേനി(സ) അവർക്ക് സമ്മതം നൽകി. അവർ പറഞ്ഞു: റസൂലേ, അബൂഖുഹാഫയുടെ മകളുടെ വിഷയത്തിൽ നീതി പുലർത്തണമെന്നാവശ്യപ്പെട്ടുകൊണ്ട് അങ്ങയുടെ പത്നിമാർ എന്നെ അയച്ചിരിക്കുന്നു. സൈനബ്(റ) എന്നെ പരിധി വിട്ടു ശകാരിച്ചു. ഈ അപരാധത്തിന് മറുപടി പറയാൻ എനിക്ക് അവിടന്ന് സമ്മതം തരുമോ എന്നറിയാൻ ഞാൻ തിരുമേനി(സ)യിലേക്കും തിരുദൂതർ(സ)യുടെ കണ്ണിലേക്കും നോക്കി. സൈനബ്(റ) ശകാരം നിർത്തിയില്ല. ഞാൻ (മറുപടി പറഞ്ഞ്) വിജയിക്കുന്നത് നബി(സ) വെറുക്കുന്നില്ല എന്ന് ഞാൻ മനസ്സിലാക്കി. ഞാൻ തിരിച്ചു ശകാരിക്കുകയും അവരെ ഉത്തരം മുട്ടിക്കുകയും ചെയ്യുന്നതുവരെ സൈനബ് ബീവി(റ) അടങ്ങിയില്ല. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "അത് അബൂബക്കറി(റ)ന്റെ മകളാണ്." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 831, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "فَضْلُ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ الثَّرِيدِ عَلَى سَائِرِ الطَّعَامِ". (ن)', 'അബൂമൂസ(റ): നബി(സ) പറയുന്നു: "മറ്റു ഭാര്യമാരേക്കാൾ ആഇശ(റ)യുടെ ശ്രേഷ്ഠത മറ്റു ഭക്ഷണത്തേക്കാൾ സരീദി (റൊട്ടിയും ഇറച്ചിയും കൂട്ടിയുണ്ടാക്കിയ ഭക്ഷണം) നുള്ള ശ്രേഷ്ഠത പോലെയാകുന്നു. (ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 833, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ نِسَاءَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَلَّمْنَهَا أَنْ تُكَلِّمَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ النَّاسَ كَانُوا يَتَحَرَّوْنَ بِهَدَايَاهُمْ يَوْمَ عَائِشَةَ، وَتَقُولُ لَهُ: إِنَّا نُحِبُّ الْخَيْرَ كَمَا تُحِبُّ عَائِشَةَ. فَكَلَّمَتْهُ فَلَمْ يُجِبْهَا، فَلَمَّا دَارَ عَلَيْهَا كَلَّمَتْهُ أَيْضًا فَلَمْ يُجِبْهَا، وَقُلْنَ: مَا رَدَّ عَلَيْكِ؟ قَالَتْ: لَمْ يُجِبْنِي. قُلْنَ: لَا تَدَعِيهِ حَتَّى يَرُدَّ عَلَيْكِ أَوْ تَنْظُرِينَ مَا يَقُولُ. فَلَمَّا دَارَ عَلَيْهَا كَلَّمَتْهُ، فَقَالَ: "لَا تُؤْذِينِي فِي عَائِشَةَ، فَإِنَّهُ لَمْ يَنْزِلْ عَلَيَّ الْوَحْيُ وَأَنَا فِي لِحَافِ امْرَأَةٍ مِنْكُنَّ إِلَّا فِي لِحَافِ عَائِشَةَ". (ن)', 'ഉമ്മുസലമ(റ): ജനങ്ങൾ അവരുടെ ഹദ്‌യ നൽകാൻ ആഇശ(റ)യുടെ ദിവസം തെരഞ്ഞെടുക്കുന്നുവെന്നും, ആഇശ(റ) നന്മയെ ഇഷ്ടപ്പെടുന്നത് പോലെതന്നെയാണ് ഞങ്ങളും ഇഷ്ടപ്പെടുന്നതെന്നും നബി(സ)യോട് (പരാതി) പറയാൻ അവിടുത്തെ ഭാര്യമാർ മഹതിയോട് പറഞ്ഞു. അങ്ങനെ ഉമ്മുസലമ(റ) നബി(സ)യോട് കാര്യം പറഞ്ഞു. പക്ഷേ, അവിടന്ന് പ്രതികരിച്ചില്ല. തന്റെ ഊഴം വന്നപ്പോൾ വീണ്ടും പറഞ്ഞു. പക്ഷേ, പ്രതികരിച്ചില്ല. മറ്റു ഭാര്യമാർ ചോദിച്ചു: തിരുമേനി(സ) എന്താണ് മറുപടി പറഞ്ഞത്? ഉമ്മുസലമ(റ) പറഞ്ഞു: എന്നോട് മറുപടി പറഞ്ഞില്ല. ഭാര്യമാർ പറഞ്ഞു: നിന്നോട് മറുപടി പറയുന്നത് വരെ നീ പറയുക. അല്ലെങ്കിൽ അവിടന്ന് എന്താണ് പറയുന്നതെന്ന് നോക്കുക. അങ്ങനെ ഊഴം വന്നപ്പോൾ അവർ കാര്യം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആഇശ(റ)യുടെ വിഷയത്തിൽ നീ എന്നെ ബുദ്ധിമുട്ടിക്കരുത്, കാരണം ആഇശയുടെ വിരിപ്പിൽ വെച്ചല്ലാതെ നിങ്ങളിൽ മറ്റൊരു ഭാര്യയുടെ വിരിപ്പിൽ വെച്ചും എനിക്ക് വഹ്‌യ് ഇറങ്ങിയിട്ടില്ല." (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 833, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّاسُ يَتَحَرَّوْنَ بِهَدَايَاهُمْ يَوْمَ عَائِشَةَ، يَبْتَغُونَ بِذَلِكَ مَرْضَاةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ആഇശ(റ): ജനങ്ങൾ അവരുടെ ഹദ്‌യകൾ നൽകാൻ ആഇശ(റ)യുടെ ദിവസം തെരഞ്ഞെടുക്കുമായിരുന്നു. അല്ലാഹുവിന്റെ റസൂൽ(സ)യുടെ തൃപ്തി കാംക്ഷിച്ചായിരുന്നു അവരങ്ങനെ ചെയ്തിരുന്നത്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 833, 833, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَوْحَى اللَّهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا مَعَهُ، فَقُمْتُ فَأَجَفْتُ الْبَابَ بَيْنِي وَبَيْنَهُ، فَلَمَّا رُفِّهَ عَنْهُ قَالَ لِي: "يَا عَائِشَةُ، إِنَّ جِبْرِيلَ يُقْرِئُكِ السَّلَامَ". وَفِي رواية: أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لَهَا: "إِنَّ جِبْرِيلَ يَقْرَأُ عَلَيْكِ السَّلَامَ". قُلْتُ: وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، تَرَى مَالَا نَرَى وَفِي رِوَايَةٍ: قَالَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، هَذَا جِبْرِيلُ، وَهُوَ يَقْرَأُ عَلَيْكِ السَّلَامَ". (ن)', 'ആഇശ(റ): ഞാൻ റസൂലുല്ലാഹി(സ)യുടെ കൂടെയായിരിക്കെ അല്ലാഹു അവിടത്തേക്ക് വഹ്യ് ഇറക്കി. ഞാൻ അവിടത്തെയും എന്റെയും ഇടയിൽ വാതിലടച്ചു. അവിടത്തെ ക്ഷീണം അകന്നപ്പോൾ എന്നോട് പറഞ്ഞു: "ആഇശാ, ജിബ്‌രീൽ(അ) നിന്നോട് സലാം പറയുന്നു." മറ്റൊരു റിപ്പോർട്ടിൽ നബി(സ) അവരോട് പറഞ്ഞു: "ജിബ്‌രീൽ(അ) നിന്റെ മേൽ സലാം പറയുന്നു." ഞാൻ (ആഇശ(റ)) പറഞ്ഞു: ''വഅലൈഹിസ്സലാം വറഹ്മത്തുല്ലാഹി വബറകാതുഹു''. ഞങ്ങൾ കാണാത്തത് അങ്ങ് കാണുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ റസൂൽ(സ) പറയുന്നു: "ആഇശാ, ഇതാ ജിബ്‌രീൽ(അ) നിനക്ക് സലാം പറയുന്നു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 833, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=10 and h.hadith_no=9), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لَهَا: "إِنَّ جِبْرِيلَ يَقْرَأُ عَلَيْكِ السَّلَامَ". قُلْتُ: وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، تَرَى مَالَا نَرَى', 'മറ്റൊരു നിവേദനിൽ നബി(സ) അവരോട് പറഞ്ഞു: "ജിബ്‌രീൽ(അ) നിന്റെ മേൽ സലാം പറയുന്നു." ഞാൻ (ആഇശ(റ)) പറഞ്ഞു: ''വഅലൈഹിസ്സലാം വറഹ്മത്തുല്ലാഹി വബറകാതുഹു''. ഞങ്ങൾ കാണാത്തത് അങ്ങ് കാണുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=10 and h.hadith_no=9), 2, 'وَفِي رِوَايَةٍ: قَالَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، هَذَا جِبْرِيلُ، وَهُوَ يَقْرَأُ عَلَيْكِ السَّلَامَ". (ن)', 'മറ്റൊരു നിവേദനിൽ റസൂൽ(സ) പറയുന്നു: "ആഇശാ, ഇതാ ജിബ്‌രീൽ(അ) നിനക്ക് സലാം പറയുന്നു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ عِنْدَ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ، فَأَرْسَلَتْ أُخْرَى بِقَصْعَةٍ فِيهَا طَعَامٌ، فَضَرَبَتْ يَدَ الرَّسُولِ فَسَقَطَتِ الْقَصْعَةُ فَانْكَسَرَتْ، فَأَخَذَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ الْكِسْرَتَيْنِ فَضَمَّ إِحْدَاهُمَا إِلَى الْأُخْرَى، فَجَعَلَ يَجْمَعُ فِيهَا الطَّعَامَ وَيَقُولُ: "غَارَتْ أُمُّكُمْ، كُلُوا". فَأَكَلُوا، فَأَمْسَكَ حَتَّى جَاءَتْ بِقَصْعَتِهَا الَّتِي فِي بَيْتِهَا، فَدَفَعَ الْقَصْعَةَ الصَّحِيحَةَ إِلَى الرَّسُولِ، وَتَرَكَ الْمَكْسُورَةَ فِي بَيْتِ الَّتِي كَسَرَتْهَا. (ن)', 'അനസ്(റ): നബി(സ) അവിടത്തെ ഭാര്യമാരിൽ (ഉമ്മഹാതുൽ മുഅ്മിനീൻ) ഒരാളുടെ വീട്ടിലായിരുന്ന ദിവസം മറ്റൊരു ഭാര്യ ഭക്ഷണത്തളിക കൊടുത്തയച്ചു. അപ്പോൾ അവർ റസൂലിന്റെ കയ്യിൽ അടിക്കുകയും തളിക താഴെ വീണുപൊട്ടുകയും ചെയ്തു. നബി(സ) രണ്ട് കഷ്ണവും എടുത്ത് കൂട്ടിപ്പിടിച്ച് ഭക്ഷണം അതിലാക്കി. അവിടന്ന് പറയുന്നുണ്ടായിരുന്നു: "നിങ്ങളുടെ മാതാവ് ദേഷ്യം പിടിച്ചിരിക്കുന്നു. നിങ്ങൾ ഭക്ഷിക്കൂ." അവർ കഴിച്ചു. ആ വീട്ടിലുള്ള പാത്രം കൊണ്ടു വരുന്നത് വരെ നബി(സ) ഭക്ഷിച്ചില്ല. അങ്ങനെ നല്ല പാത്രം കൊണ്ടുവരികയും അത് ഭക്ഷണത്തളിക കൊണ്ടുവന്നയാൾക്ക് കൊടുക്കുകയും ചെയ്തു. പൊട്ടിയ പാത്രം ആ വീട്ടിൽ തന്നെ വെച്ചു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا يَعْنِي أَتَتْ بِطَعَامٍ فِي صَحْفَةٍ لَهَا إِلَى رَسُولِ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ وَأَصْحَابِهِ، فَجَاءَتْ عَائِشَةُ مُتَّزِرَةً بِكِسَاءٍ وَمَعَهَا فِهْرٌ، فَفَلَقَتْ بِهِ الصَّحْفَةَ، فَجَمَعَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ بَيْنَ فِلْقَتَيِ الصَّحْفَةِ وَيَقُولُ: "كُلُوا، غَارَتْ أُمُّكُمْ". مَرَّتَيْنِ، ثُمَّ أَخَذَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ صَحْفَةَ عَائِشَةَ، فَبَعَثَ بِهَا إِلَى أُمِّ سَلَمَةَ، وَأَعْطَى صَحْفَةَ أُمِّ سَلَمَةَ عَائِشَةَ. (ن)', 'ഉമ്മുസലമ(റ): അവർ നബി(സ)ക്കും അവിടത്തെ അനുചരൻമാർക്കും വേണ്ടി ഒരു തളികയിൽ ഭക്ഷണം കൊണ്ടുവന്നു. അപ്പോൾ ആഇശ(റ) തുണി അരയിൽ മുറുക്കുകയും ഒരു കല്ലെടുത്ത് ആ പാത്രം പൊട്ടിക്കുകയും ചെയ്തു. നബി(സ) രണ്ട് പൊളികളുമെടുത്ത് ഒന്നിപ്പിച്ച് ഇങ്ങനെ രണ്ട്പ്രാവശ്യം പറഞ്ഞു: "നിങ്ങൾ കഴിക്കൂ, നിങ്ങളുടെ ഉമ്മ ദേഷ്യപ്പെട്ടിരിക്കുന്നു." ശേഷം റസൂൽ(സ) ആഇശ(റ)യുടെ പാത്രം എടുക്കുകയും അത് ഉമ്മുസലമ(റ)ക്ക് കൊടുത്തയക്കുകയും ഉമ്മുസലമ(റ)യുടെ പാത്രം ആഇശ(റ)ക്ക് നൽകുകയും ചെയ്തു. (ന)', 'أَمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَائِشَةَ رَضِيَ الله عَنْهَا قَالَتْ: مَا رَأَيْتُ صَانِعَةَ طَعَامٍ مِثْلَ صَفِيَّةَ، أَهْدَتْ إِلَى النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ إِنَاءً فِيهِ طَعَامٌ، فَمَا مَلَكْتُ نَفْسِي أَنْ كَسَرْتُهُ، فَسَأَلْتُ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ عَنْ كَفَّارَتِهِ؟ فَقَالَ: "إِنَاءٌ كَإِنَاءٍ، وَطَعَامٌ كَطَعَامٍ". (ن)', 'ആഇശ(റ): സ്വഫിയ്യ(റ)യെപ്പോലെ ഒരു പാചകക്കാരിയെയും ഞാൻ കണ്ടിട്ടില്ല. അവർ ഒരു ഭക്ഷണത്തളിക നബി(സ)ക്ക് കൊടുത്തയച്ചു. അപ്പോൾ എനിക്കത് പൊട്ടിക്കാതിരിക്കാൻ കഴിഞ്ഞില്ല. അപ്പോൾ ഞാൻ നബി(സ)യോട് അതിന്റെ പ്രായശ്ചിത്തത്തെക്കുറിച്ച് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "ആ പാത്രത്തെ പോലുള്ള ഒരു പാത്രവും ആ ഭക്ഷണത്തെ പോലുള്ള ഒരു ഭക്ഷണവും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 834, 835, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْكُثُ عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ، فَيَشْرَبُ عِنْدَهَا عَسَلًا، فَتَوَاصَيْتُ أَنَا وَحَفْصَةُ: أَنَّ أَيَّتَنَا دَخَلَ عَلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلْتَقُلْ: إِنِّي أَجِدُ مِنْكَ رِيحَ مَغَافِيرَ، أَكَلْتَ مَغَافِيرَ. فَدَخَلَ عَلَى إِحْدَاهُمَا فَقَالَتْ ذَلِكَ لَهُ، فَقَالَ: "لَا، بَلْ شَرِبْتُ عَسَلًا عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ، وَلَنْ أَعُودَ لَهُ". فَنَزَلَتْ: {يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ} {إِنْ تَتُوبَا إِلَى اللَّهِ} [التحريم: ١] لِعَائِشَةَ وَحَفْصَةَ. {وَإِذْ أَسَرَّ النَّبِيُّ إِلَى بَعْضِ أَزْوَاجِهِ حَدِيثًا} لِقَوْلِهِ: "بَلْ شَرِبْتُ عَسَلًا". (ن)', 'ആഇശ(റ): റസൂൽ(സ) സൈനബ് ബിൻത് ജഹ്ശ്(റ)യുടെ അടുത്ത് താമസിക്കുകയും അവിടന്ന് തേൻ കുടിക്കുകയും ചെയ്യും. അപ്പോൾ ഞാനും സ്വഫിയ്യയും അന്യോന്യം പറഞ്ഞു: നമ്മളിലൊരാളുടെ അടുത്തേക്ക് നബി(സ) കടന്നുവന്നാൽ ഇപ്രകാരം പറയണം: അവിടുന്ന് മഗാഫീർ കഴിച്ചിട്ടുണ്ടോ? അതിന്റെ വാസന വരുന്നു. അങ്ങനെ റസൂൽ അവരിലൊരാളുടെ അടുത്ത് വന്നപ്പോൾ അവർ അപ്രകാരം ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "ഇല്ല, പക്ഷേ, ഞാൻ സൈനബ്(റ)യുടെ അടുത്ത് നിന്ന് തേൻ കുടിച്ചിരുന്നു. ഇനി ഞാൻ അതിന് വേണ്ടി അവിടേക്ക് പോകുകയില്ല." അപ്പോൾ ഈ ആയത് ഇറങ്ങി: ''നബിയേ, അങ്ങെന്തിനാണ് അങ്ങയുടെ പത്നിമാരുടെ പ്രീതിക്കുവേണ്ടി, അങ്ങേക്ക് അല്ലാഹു അനുവദിച്ചു തന്നത് നിഷിദ്ധമാക്കുന്നത്.'' ''നിങ്ങൾ രണ്ടുപേരും അല്ലാഹുവിലേക്ക് പശ്ചാത്തപിച്ചു മടങ്ങുന്നുവെങ്കിൽ''. (തഹ്‌രീം:1) ഇത് ആഇശ(റ)യോടും ഹഫ്സ(റ)യോടുമാണ്. ''നബി(സ) അവിടത്തെ ഭാര്യമാരിൽ ചിലരോട് രഹസ്യം പറഞ്ഞ സന്ദർഭം'' എന്നത് നബി(സ)യുടെ "ഞാൻ തേൻ കുടിച്ചു" എന്ന വാക്കിനെക്കുറിച്ചാണ്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'التحريم: ١', null, 835, 835, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَلَا أُحَدِّثُكُمْ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَنِّي؟ قُلْنَا: بَلَى. قَالَتْ: لَمَّا كَانَتْ لَيْلَتِي انْقَلَبَ فَوَضَعَ نَعْلَيْهِ عِنْدَ رِجْلَيْهِ، وَوَضَعَ رِدَاءَهُ وَبَسَطَ - طَرَفَ- إِزَارِهِ عَلَى فِرَاشِهِ، فَلَمْ يَلْبَثْ إِلَّا رَيْثَمَا ظَنَّ أَنِّي قَدْ رَقَدْتُ، ثُمَّ انْتَعَلَ رُوَيْدًا وَأَخَذَ رِدَاءَهُ رُوَيْدًا، ثُمَّ فَتَحَ الْبَابَ رُوَيْدًا وَخَرَجَ وَأَجَافَهُ رُوَيْدًا، وَجَعَلْتُ دِرْعِي فِي رَأْسِي وَاخْتَمَرْتُ، وَتَقَنَّعْتُ إِزَارِي فَانْطَلَقْتُ فِي إِثْرِهِ حَتَّى جَاءَ الْبَقِيعَ، فَرَفَعَ يَدَيْهِ ثَلَاثَ مَرَّاتٍ، وَأَطَالَ الْقِيَامَ، ثُمَّ انْحَرَفَ فَانْحَرَفْتُ، فَأَسْرَعَ فَأَسْرَعْتُ، فَهَرْوَلَ فَهَرْوَلْتُ، فَأَحْضَرَ فَأَحْضَرْتُ، وَسَبَقْتُهُ فَدَخَلْتُ، فَلَيْسَ إِلَّا أَنِ اضْطَجَعْتُ فَدَخَلَ، فَقَالَ: "مَا لَكِ يَا عَائِشَةُ حَشْيَا". وفي رواية: "يا عائشة، حشيا رابية". قَالَتْ: لَا. قَالَ: "لَتُخْبِرَنِّي أَوْ لَيُخْبِرَنِّي اللَّطِيفُ الْخَبِيرُ". قُلْتُ: يَا رَسُولَ اللَّهِ، بِأَبِي أَنْتَ وَأُمِّي، فَأَخْبَرْتُهُ الْخَبَرَ، قَالَ: "فَأَنْتِ السَّوَادُ الَّذِي رَأَيْتُهُ أَمَامِي". قلت: نَعَمْ. قَالَتْ: فَلَهَدَنِي فِي صَدْرِي لَهْدَةً أَوْجَعَتْنِي. قَالَ: "أَظَنَنْتِ أَنْ يَحِيفَ اللَّهُ عَلَيْكِ وَرَسُولُهُ". قَالَتْ: مَهْمَا يَكْتُمِ النَّاسُ فَقَدْ عَلِمَهُ اللَّهُ عَزَّ وَجَلَّ. قَالَ: "نَعَمْ". قَالَ: "فَإِنَّ جِبْرِيلَ عَلَيْهِ السَّلَامُ أَتَانِي حِينَ رَأَيْتِ، وَلَمْ يَكُنْ يَدْخُلُ عَلَيْكِ وَقَدْ وَضَعْتِ ثِيَابَكِ، فَنَادَانِي فَأَخْفَى مِنْكِ، فَأَجَبْتُهُ فَأَخْفَيْتُ مِنْكِ، فَظَنَنْتُ أَنَّكِ قَدْ رَقَدْتِ فَكَرِهْتُ أَنْ أُوقِظَكِ، وَخَشِيتُ أَنْ تَسْتَوْحِشِي، فَأَمَرَنِي أَنْ آتِيَ أَهْلَ الْبَقِيعِ فَأَسْتَغْفِرَ لَهُمْ". (ن)', 'ആഇശ(റ): അവർ പറയുന്നു: എന്നെക്കുറിച്ചും നബി(സ)യെക്കുറിച്ചും നിങ്ങൾക്ക് ഞാൻ പറഞ്ഞു തരട്ടെയോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: എന്റെ കൂടെ കഴിച്ചുകൂട്ടിയ ഒരു രാത്രിയിൽ തിരുമേനി(സ) ഇശാനിസ്കാരം കഴിഞ്ഞതിന് ശേഷം ചെരുപ്പുകൾ തന്റെ കാലിന്റെ അരികിൽ വെച്ചു. മേൽ തട്ടം താഴെവെക്കുകയും തന്റെ വിരിപ്പിൽ തുണിയുടെ ഒരു ഭാഗം വിരിക്കുകയും ചെയ്തു. കുറച്ചു കഴിഞ്ഞപ്പോൾ ഞാൻ ഉറങ്ങിയെന്ന് കരുതി നബി(സ) പതുക്കെ ചെരിപ്പു ധരിക്കുകയും മേൽതട്ടം എടുക്കുകയും ചെയ്തു. പിന്നെ പതുക്കെ വാതിൽ തുറന്ന് പുറത്തു കടന്ന് വാതിൽ അടച്ചു. ഞാനെന്റെ വസ്ത്രമെടുത്തിട്ട് മുഖം മറച്ചു. വസ്ത്രം ധരിച്ചു. നബി(സ)യുടെ പിന്നാലെ പോയി. അങ്ങനെ നബി(സ) ''ജന്നതുൽ ബഖീഇ''ൽ പ്രവേശിച്ചു. തിരുമേനി(സ) മൂന്നു തവണ കൈ ഉയർത്തി. ദീർഘ നേരം നിന്നു. പിന്നെ നബി(സ) മടങ്ങി. ഞാനും മടങ്ങി. നബി(സ) വേഗത കൂട്ടി, ഞാനും. അങ്ങനെ നബി(സ) കയറും മുമ്പേ ഞാൻ വീട്ടിൽ കയറി. ഞാൻ കിടന്നപ്പോഴേക്കും നബി(സ) എത്തി. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ആഇശാ, എന്താ നീ ഇങ്ങനെ കിതക്കുന്നത്?" അവർ പറഞ്ഞു: ഒന്നുമില്ല. തിരുമേനി(സ) പറഞ്ഞു: "നീ എന്നോട് പറയുക, അല്ലെങ്കിൽ ദയാലുവും സൂക്ഷ്മ ജ്ഞാനിയുമായ (അല്ലാഹു) എനിക്ക് അറിയിച്ചുതരും". അവർ പറഞ്ഞു: റസൂലേ, എന്റെ ഉമ്മയും ഉപ്പയും അങ്ങേക്ക് ദണ്ഡമാണ്. ശേഷം നബി(സ)ക്ക് സംഭവം വിവരിച്ചുകൊടുത്തു. തിരുമേനി(സ) പറഞ്ഞു: "നീയായിരന്നോ എന്റെ മുന്നിലുണ്ടായുരന്ന കറുത്ത രൂപം?". അവർ പറഞ്ഞു: അതെ. ആഇശ(റ) പറയുന്നു. അപ്പോൾ നബി(സ) എനിക്ക് വേദനിക്കും വിധം എന്റെ നെഞ്ചത്ത് ഒരു ഇടി ഇടിച്ചു. നബി(സ) ചോദിച്ചു: "അല്ലാഹുവും അവന്റെ ദൂതനും നിന്നോട് അക്രമം പ്രവർത്തിക്കുമെന്ന് നീ കരുതുന്നുണ്ടോ?" അവർ പറഞ്ഞു: ജനങ്ങൾ മറച്ചുവെക്കുന്നത് അല്ലാഹു അറിയും. നബി(സ) പറഞ്ഞു: "അതെ, ജിബ്‌രീൽ(അ) എന്റെ അടുത്ത് വന്നു. ഞാൻ നിന്റെകൂടെ കിടക്കുമ്പോൾ ജിബ്‌രീൽ (അ) വരാറില്ലായിരുന്നു. ജിബ്‌രീൽ(അ) എന്നെ വിളിച്ചു. ഞാൻ മറുപടി നൽകി. ഞാനത് നീ അറിയാതിരിക്കാൻ പതുക്കെയാക്കി. നീ ഉറങ്ങിയിട്ടുണ്ടാവുമെന്ന് കരുതി. നിന്നെ ഉണർത്താൻ ഞാനിഷ്ടപ്പെട്ടില്ല. നിന്നെ വല്ല മൃഗവും പിടിക്കുമെന്ന് ഞാൻ ഭയപ്പെട്ടു. ബഖീഇൽ വരാനും അവർക്ക് വേണ്ടി പൊറുക്കലിനെ തേടാനും ജിബ്‌രീൽ എന്നോട് കൽപ്പിച്ചു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 835, 836, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=10 and h.hadith_no=14), 1, 'وَفِي رِوَايَةٍ: "يا عائشة، حشيا رابية". قَالَتْ: لَا. قَالَ: "لَتُخْبِرَنِّي أَوْ لَيُخْبِرَنِّي اللَّطِيفُ الْخَبِيرُ". قُلْتُ: يَا رَسُولَ اللَّهِ، بِأَبِي أَنْتَ وَأُمِّي، فَأَخْبَرْتُهُ الْخَبَرَ، قَالَ: "فَأَنْتِ السَّوَادُ الَّذِي رَأَيْتُهُ أَمَامِي". قلت: نَعَمْ. قَالَتْ: فَلَهَدَنِي فِي صَدْرِي لَهْدَةً أَوْجَعَتْنِي. قَالَ: "أَظَنَنْتِ أَنْ يَحِيفَ اللَّهُ عَلَيْكِ وَرَسُولُهُ". قَالَتْ: مَهْمَا يَكْتُمِ النَّاسُ فَقَدْ عَلِمَهُ اللَّهُ عَزَّ وَجَلَّ. قَالَ: "نَعَمْ". قَالَ: "فَإِنَّ جِبْرِيلَ عَلَيْهِ السَّلَامُ أَتَانِي حِينَ رَأَيْتِ، وَلَمْ يَكُنْ يَدْخُلُ عَلَيْكِ وَقَدْ وَضَعْتِ ثِيَابَكِ، فَنَادَانِي فَأَخْفَى مِنْكِ، فَأَجَبْتُهُ فَأَخْفَيْتُ مِنْكِ، فَظَنَنْتُ أَنَّكِ قَدْ رَقَدْتِ فَكَرِهْتُ أَنْ أُوقِظَكِ، وَخَشِيتُ أَنْ تَسْتَوْحِشِي، فَأَمَرَنِي أَنْ آتِيَ أَهْلَ الْبَقِيعِ فَأَسْتَغْفِرَ لَهُمْ". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَتْ لَهُ أَمَةٌ يَطَؤُهَا، فَلَمْ تَزَلْ بِهِ عَائِشَةُ وَحَفْصَةُ حَتَّى حَرَّمَهَا عَلَى نَفْسِهِ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ} إِلَى آخِرِ الْآيَةِ. (ن)', 'അനസ്(റ): റസൂൽ(സ)ക്ക് അവിടന്ന് ബന്ധപ്പെടാറുണ്ടായിരുന്ന ഒരു അടിമസ്ത്രീ ഉണ്ടായിരുന്നു. അപ്പോൾ ആഇശ(റ)യും ഹഫ്സ(റ)യും നബി(സ) ആ അടിമസ്ത്രീയെ ഒഴിവാക്കുന്നത് വരെ പറഞ്ഞ് കൊണ്ടേ ഇരുന്നു. അങ്ങനെ അല്ലാഹു ഈ ആയത്തിറക്കി. ''നബിയെ, അല്ലാഹു അങ്ങേക്ക് അനുവദനീയമാക്കിയതിനെ എന്തുകൊണ്ടാണ് താങ്കൾ നിഷിദ്ധമാക്കിയത്?'' (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 836, 836, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: الْتَمَسْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَدْخَلْتُ يَدِي فِي شَعْرِهِ، فَقَالَ: "قَدْ جَاءَكِ شَيْطَانُكِ". فَقُلْتُ: أَمَا لَكَ شَيْطَانٌ؟ فَقَالَ: "بَلَى، وَلَكِنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَأَسْلَمَ". (ن)', 'ആഇശ(റ): ഞാൻ തിരുദൂതർ(സ)യെ പരതി. അങ്ങനെ എന്റെ കൈ അവിടത്തെ മുടിയിൽ തട്ടി. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിന്നിലേക്ക് നിന്റെ പിശാച് വന്നിട്ടുണ്ട്." ഞാൻ ചോദിച്ചു: അങ്ങേക്ക് പിശാചുണ്ടോ? അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അതെ, പക്ഷേ അവന്റെ മേൽ അല്ലാഹു എന്നെ സഹായിച്ചിരിക്കുന്നു. അത് കൊണ്ടവൻ മുസ്‌ലിമായി." (ന).', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 836, 836, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: افْتَقَدْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَظَنَنْتُ أَنَّهُ ذَهَبَ إِلَى بَعْضِ نِسَائِهِ، فَتَجَسَّسْتُ ثُمَّ رَجَعْتُ فَإِذَا هُوَ رَاكِعٌ أَوْ سَاجِدٌ، يَقُولُ: "سُبْحَانَكَ وَبِحَمْدِكَ، لَا إِلَهَ إِلَّا أَنْتَ". فَقُلْتُ: بِأَبِي وَأُمِّي، إِنَّكَ لَفِي شَأْنٍ وَإِنِّي لَفِي آخَرَ. (ن)', 'ആഇശ(റ): ഒരു രാത്രി ഞാൻ റസൂൽ(സ)യെ കാണാതായി. അവിടന്ന് മറ്റുവല്ല ഭാര്യമാരിലേക്കും പോയെന്ന് ഞാൻ കരുതി. അങ്ങനെ ഞാൻ പരതി നോക്കി തിരിച്ച് വന്നപ്പോൾ അവിടന്ന് റുകൂഇലോ സുജൂദിലോ ആയിരിക്കുന്നതാണ് ഞാൻ കണ്ടത്. അവിടന്ന് പറയുന്നുണ്ടായിരുന്നു: "നീ എത്ര പരിശുദ്ധനാണ്. നിനക്കാണ് സർവ്വ സ്തുതിയും, നീ മാത്രമാണ് ആരാധ്യൻ." ഞാൻ പറഞ്ഞു: എന്റെ ഉമ്മയെയും ബാപ്പയെയും അങ്ങേക്ക് ഞാൻ സമർപ്പിക്കുന്നു, തീർച്ചയായും അങ്ങ് ഒരു വിഷയത്തിലും ഞാൻ മറ്റൊരു വിഷയത്തിലുമായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 836, 836, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
